import React, { useState } from "react";
import { PROJECTS } from "../../data/projects";
import SectionHeader from "../common/SectionHeader";
import chubImg from "../../assets/chub_logo.png";
import pitcraftImg from "../../assets/pitcraft_screenshot_1.jpg";
import appLogoClean from "../../assets/laplayer_logo.png";
import magiktarotImg from "../../assets/magik_tarot_logo.png";
import stickersbotImg from "../../assets/stickers_bot_logo.png";
import gameOfDronesImg from "../../assets/game_of_drones_logo.png";
import bleachcoImg from "../../assets/bleach_co_logo.png";
import agentTyImg from "../../assets/agent_ty.png";
import escribaImg from "../../assets/escriba_icon.png";
import dsLogoImg from "../../assets/ds_icon.png";
import eriumImg from "../../assets/erium_logo.jpg";
import whatsappbotImg from "../../assets/whatsapp_bot_screenshot.jpg";
import tv2Img from "../../assets/tv2_card_logo.png";
import engajaLogo from "../../assets/engaja_logo.jpg";
import n8nLogo from "../../assets/n8n_logo.png";
import chatwootLogo from "../../assets/chatwoot_logo.png";
import farmaisLogo from "../../assets/farmais_logo.jpg";
import imobsystemLogo from "../../assets/imobsystem_logo.jpg";

const getProjectPlaceholder = (color) => {
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="350" height="180" viewBox="0 0 350 180"><rect width="100%" height="100%" fill="#0c081e"/><defs><pattern id="grid" width="20" height="20" patternUnits="userSpaceOnUse"><path d="M 20 0 L 0 0 0 20" fill="none" stroke="${color}20" stroke-width="1"/></pattern><linearGradient id="grad" x1="0%" y1="0%" x2="100%" y2="100%"><stop offset="0%" stop-color="${color}35"/><stop offset="100%" stop-color="#0c081e"/></linearGradient></defs><rect width="100%" height="100%" fill="url(#grid)"/><rect width="100%" height="100%" fill="url(#grad)"/><circle cx="175" cy="90" r="45" fill="none" stroke="${color}30" stroke-width="1.5" stroke-dasharray="5,5"/><circle cx="175" cy="90" r="28" fill="none" stroke="${color}b3" stroke-width="2"/></svg>`;
  return `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`;
};

export default function ProjectsPage({ lang, setPage }) {
  const pt = lang === "pt";
  const [openId, setOpenId] = useState(null);

  const toggleOpen = (id) => {
    setOpenId(openId === id ? null : id);
  };

  return (
    <div className="page">
      <div className="section">
        <SectionHeader
          tag={pt ? "portfólio" : "portfolio"}
          title={
            pt ? (
              <>O que eu <em>construí</em></>
            ) : (
              <>What I've <em>built</em></>
            )
          }
          sub={pt ? "Clique em qualquer projeto para expandir e ver detalhes." : "Click any project to expand and view details."}
        />

        <div className="projects-grid">
          {PROJECTS.map((p, idx) => {
            const isOpen = openId === p.id;
            const isFeatured = idx % 3 === 0;
            return (
              <div
                key={p.id}
                data-id={p.id}
                className={`pcard${isOpen ? " open" : ""}${isFeatured ? " featured" : ""}`}
                style={{ "--card-glow": `${p.color}20` }}
                onClick={() => toggleOpen(p.id)}
              >
                <div className="pcard-image-wrapper">
                  <img
                    src={
                      p.id === "chub"
                        ? chubImg
                        : p.id === "pitcraft"
                        ? pitcraftImg
                        : p.id === "laplayer"
                        ? appLogoClean
                        : p.id === "magik-tarot"
                        ? magiktarotImg
                        : p.id === "bot-figurinhas"
                        ? stickersbotImg
                        : p.id === "whatsapp-bot"
                        ? whatsappbotImg
                        : p.id === "erium"
                        ? eriumImg
                        : p.id === "tv2"
                        ? tv2Img
                        : p.id === "drone-autonomo"
                        ? gameOfDronesImg
                        : p.id === "bleach-co"
                        ? bleachcoImg
                        : p.id === "portfolio"
                        ? agentTyImg
                        : p.id === "cvmaker"
                        ? `data:image/svg+xml;utf8,${encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="180" height="180" viewBox="0 0 180 180"><rect width="100%" height="100%" fill="#1e40af"/><text x="90" y="90" font-family="sans-serif" font-size="95" text-anchor="middle" dominant-baseline="central">🎯</text></svg>')}`
                        : p.id === "dshub"
                        ? dsLogoImg
                        : p.id === "escriba"
                        ? escribaImg
                        : p.id === "engaja-site"
                        ? engajaLogo
                        : p.id === "n8n-forms"
                        ? n8nLogo
                        : p.id === "chatwoot-custom"
                        ? chatwootLogo
                        : p.id === "farmais"
                        ? farmaisLogo
                        : p.id === "imobsystem"
                        ? imobsystemLogo
                        : getProjectPlaceholder(p.color)
                    }
                    alt={pt ? p.namePt : p.nameEn}
                    className="pcard-image"
                  />
                </div>
                <div className="pcard-header">
                  <div className="pcard-name">{pt ? p.namePt : p.nameEn}</div>
                  <div className="pcard-tags">
                    {p.tags.slice(0, 3).map((t, idx) => (
                      <span key={t} className={`chip ${idx === 0 ? "chip-type" : "chip-p"}`}>{t}</span>
                    ))}
                  </div>
                </div>

                <div className="pcard-expand-wrapper">
                  <div className="pcard-tagline">{pt ? p.taglinePt : p.taglineEn}</div>
                  <p className="pcard-desc">{pt ? p.descPt : p.descEn}</p>
                  
                  <div className="pcard-actions" onClick={(e) => e.stopPropagation()}>
                    <button
                      className="btn btn-fill btn-sm"
                      onClick={() => {
                        const targetKey = 
                          p.id === "whatsapp-bot" ? "whatsappbot" :
                          p.id === "drone-autonomo" ? "gameofdrones" :
                          p.id === "bot-figurinhas" ? "stickerbot" :
                          p.id === "discord-bot" ? "discordbot" :
                          p.id === "magik-tarot" ? "magiktarot" :
                          p.id;
                        setPage(targetKey);
                      }}
                    >
                      {p.id === "pitcraft" ? (pt ? "Acessar Hub" : "Access Hub") : (pt ? "Ver Detalhes" : "View Details")} &rarr;
                    </button>
                    {p.link && (
                      <a
                        href={p.link}
                        target="_blank"
                        rel="noreferrer"
                        className="btn btn-outline btn-sm"
                      >
                        {p.link.includes("github.com") ? (pt ? "Repositório" : "Repository") : (pt ? "Acessar Aplicação" : "Open App")} &rarr;
                      </a>
                    )}
                    {p.apk && p.id !== "laplayer" && (
                      <a
                        href={p.apk}
                        download
                        className="btn btn-outline btn-sm"
                        style={{ display: "inline-flex", alignItems: "center", gap: "0.5rem" }}
                      >
                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" style={{ width: "13px", height: "13px" }}>
                          <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4" />
                          <polyline points="7 10 12 15 17 10" />
                          <line x1="12" y1="15" x2="12" y2="3" />
                        </svg>
                        <span>{pt ? "Baixar APK" : "Download APK"}</span>
                      </a>
                    )}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}
