export const API_CONFIG = {
    BACKEND_URL: 'https://api-pitsite.magiktarot.com.br',
    ENDPOINTS: {
        chat: '/chat',
        health: '/health',
        config: '/config',
        calendarHealth: '/calendar/health',
        calendarAvailability: '/calendar/availability',
        calendarBook: '/calendar/book',
    }
};

export function getApiUrl(endpoint) {
    const baseUrl = API_CONFIG.BACKEND_URL;
    const path = API_CONFIG.ENDPOINTS[endpoint] || endpoint;
    return `${baseUrl}${path}`;
}
